"use strict";
// The module-initialization fence the SDKs pi uses have: a class expression
// that extends Promise at module scope, which the native compiler refuses.
class SdkPromise extends Promise {}
exports.SdkPromise = SdkPromise;
exports.create = (params, input, options) => {
  const body = JSON.stringify(params);
  params.normalized = true;
  const content = typeof params.metadata === "object" && params.metadata !== null ? params.metadata.tag : null;
  return {
    id: "resp_" + body.length + "_" + ((options && options.betas) || []).join("|"),
    choices: [{ message: { content: content === undefined ? null : content, tool_calls: Array.isArray(params.tools) ? params.tools.map((t) => ({ id: t.name })) : [] } }],
  };
};
exports.same = (value) => value;
exports.assistant = () => ({ role: "assistant", content: null });
